#!/usr/bin/env python3
"""Write video2/previz/BEATS.md: per beat, the storyboard's current bg + sprites, so frames B### can be filled in Figma."""
import json, os
V2 = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '../../projects/bluepill/video2'))
sb = json.load(open(os.path.join(V2, 'storyboard.json')))
L = ['# BEATS.md: one Figma frame per beat (name it B###, three digits)', '',
     'Current storyboard state per beat (generated by scripts/figma/make_beats.py). Sprite = id @ x,y(feet),h. `bg` = background asset or type. Beats with several shots: frame B### patches the first shot; name extra frames `B###_sNNN` (shot id) to patch the others.', '',
     '| frame | shots | bg | sprites now |', '|---|---|---|---|']
byb = {}
for s in sb['shots']: byb.setdefault(s['beat'], []).append(s)
for b in sorted(byb):
    shots = byb[b]
    for s in shots:
        bg = s['bg'].get('src') or s['bg']['type']
        sp = ['%s @%d,%d,h%d%s' % (e['src'][:-4], e['x'], e['y'], e['h'], ' mirror' if e.get('mirror') else '') + (' inset' if e.get('inset') else '')
              for e in sb['events'] if e['shot'] == s['id'] and e['kind'] == 'sprite']
        name = 'B%03d' % b if s is shots[0] else 'B%03d_%s' % (b, s['id'])
        L.append('| %s | %s | %s | %s |' % (name, s['id'], bg, '; '.join(sp) or '-'))
open(os.path.join(V2, 'previz/BEATS.md'), 'w').write('\n'.join(L) + '\n')
print(len(byb), 'beats')
